'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float32Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float32Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `forEach` method for iterating over each element', function test( t ) {
	var arr = new Float32Array( 2 );
	t.strictEqual( hasProp( arr, 'forEach' ), true, 'has property' );
	t.strictEqual( isFunction( arr.forEach ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a typed array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.forEach.call( value, fcn );
		};
	}

	function fcn() {
		// no-op
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 10 );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.forEach( value );
		};
	}
});

tape( 'the method should not invoke a provided callback function if operating on an empty typed array', function test( t ) {
	var arr;

	arr = new Float32Array();
	arr.forEach( fcn );

	t.end();

	function fcn() {
		t.fail( 'should not be invoked' );
	}
});

tape( 'the method invokes a provided function for each element', function test( t ) {
	var count;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	count = 0;

	arr.forEach( function fcn( v, i ) {
		t.strictEqual( typeof v, 'number', 'returns expected value' );
		t.strictEqual( v, arr[ i ], 'returns expected value' );
		count += 1;
	});

	t.strictEqual( count, 3, 'returns expected value' );
	t.end();
});

tape( 'the method invokes a provided function with the correct arguments', function test( t ) {
	var indices;
	var values;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	indices = [];
	values = [];

	arr.forEach( function fcn( v, i ) {
		values.push( v );
		indices.push( i );
	});

	t.deepEqual( values, [ 1.0, 2.0, 3.0 ], 'returns expected value' );
	t.deepEqual( indices, [ 0, 1, 2 ], 'returns expected value' );
	t.end();
});

tape( 'the method supports providing an execution context', function test( t ) {
	var ctx;
	var arr;

	ctx = {
		'count': 0
	};
	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	arr.forEach( fcn, ctx );

	t.strictEqual( ctx.count, 3, 'returns expected value' );
	t.end();

	function fcn() {
		this.count += 1; // eslint-disable-line no-invalid-this
	}
});
